#!/bin/sh
# Writes ios/SaySoApp/Generated/Secrets.swift from the repo's .env (both gitignored).
# Run after changing SAYSO_API_URL / SAYSO_API_TOKEN:  sh ios/scripts/gen_secrets.sh
set -e
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
get() { grep "^$1=" "$ROOT/.env" | cut -d= -f2-; }
URL="$(get SAYSO_API_URL)"
TOKEN="$(get SAYSO_API_TOKEN)"
[ -n "$URL" ] && [ -n "$TOKEN" ] || { echo "SAYSO_API_URL or SAYSO_API_TOKEN missing in .env" >&2; exit 1; }
mkdir -p "$ROOT/ios/SaySoApp/Generated"
cat > "$ROOT/ios/SaySoApp/Generated/Secrets.swift" <<EOF
// Generated by ios/scripts/gen_secrets.sh — do not commit.
import Foundation

enum Secrets {
    static let apiURL = URL(string: "$URL")!
    static let apiToken = "$TOKEN"
}
EOF
echo "wrote ios/SaySoApp/Generated/Secrets.swift"
